  <script>
    // Slot selection
    (function(){
      const slots = document.querySelectorAll('.slot');
      let selectedSlot = null;
      slots.forEach(s => s.addEventListener('click', ()=>{
        slots.forEach(x=>x.classList.remove('selected'));
        s.classList.add('selected'); selectedSlot = s.dataset.slot;
      }));

      // Service and price live update
      const serviceSel = document.getElementById('service');
      const selectedService = document.getElementById('selectedService');
      const selectedPrice = document.getElementById('selectedPrice');
      const compPrice = document.getElementById('compPrice');

      const priceMap = {seed:120, renewal:240, revive:800};
      function updatePrice(mode){
        const key = serviceSel.value;
        let val = priceMap[key];
        if(mode === 'monthly'){
          compPrice.textContent = '$' + val;
          selectedPrice.textContent = '$' + val + (key==='renewal'? ' • Monthly':' • 60 minutes');
        } else {
          // package pricing discounts
          const pk = key==='revive' ? val : Math.round(val*2.8);
          compPrice.textContent = '$' + pk;
          selectedPrice.textContent = '$' + pk + ' • package';
        }
      }

      document.getElementById('cmpMonthly').addEventListener('click', ()=> updatePrice('monthly'));
      document.getElementById('cmpPackage').addEventListener('click', ()=> updatePrice('package'));
      serviceSel.addEventListener('change', ()=>{ selectedService.textContent = serviceSel.options[serviceSel.selectedIndex].text; updatePrice('monthly'); });

      // initialize
      updatePrice('monthly');

      // Form basic validation and attach selected slot value
      const form = document.getElementById('bookingForm');
      form.addEventListener('submit', function(e){
        if(!selectedSlot){
          e.preventDefault(); alert('Please pick a preferred time slot.'); return false;
        }
        const input = document.createElement('input'); input.type='hidden'; input.name='preferred_slot'; input.value = selectedSlot; form.appendChild(input);
        // allow submit to proceed to server URL
      });
    })();
